"""Reproducible record-by-record authoring of the B slice (682--697).

Run from the repository root.  Every completed record is checkpointed by save().
Sources and research operations are documented in the adjacent searchNN.json logs.
"""
import json, pathlib, re, csv
OUT = pathlib.Path('parts/B')
talks, items, problems, corrections = [], [], [], []
STATUS = r'As of 12 November 2026 this is an established result under the hypotheses in the modern statement.'
def talk(record, date, speaker, pages, title, summary):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind='talk',summary=summary))
def item(record, pages, kind, title, notes, statement, fate, refs=(), **kw):
    n=1+sum(x['record']==record for x in items)
    d=dict(id=f'1986-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction='',fate=fate,refs=list(refs),present_status=STATUS,literal_correctness='correct with missing hypotheses',publication_match='exact',verification='read the result',development='none',problem='',worth='',confidence='high')
    d['class']=kw.pop('cls','E'); d.update(kw);items.append(d);return d['id']
def problem(pid,title,statement,occurrences,status,refs):
    problems.append(dict(id=pid,title=title,statement=statement,occurrences=occurrences,status=status,status_date='2026-11',refs=refs))
def corr(page,place,reads,should,evidence,applies='both',typ='faithful_error'):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=typ))
def save():
    OUT.mkdir(exist_ok=True)
    for name,data in [('talks',talks),('items',items),('problems',problems)]:
        (OUT/f'{name}.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    with (OUT/'corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)

talk(682,'1986-09-29','V. A. Kazakov','P001297-P001299','Planar maps, matrix integrals, and two-dimensional gravity',r'The catalogue range overlaps Ginzburg and Ovsienko. Kazakov actually begins in the lower part of P001298 and continues through P001302: triangulated spheres, the cubic Hermitian matrix model, its planar expansion, eigenvalue saddle, and critical exponent. The formal combinatorial integral must be distinguished from a convergent integral over real Hermitian matrices. Record 695 revisits the counting conventions.')
item(682,'P001298-P001299','construction','Triangulations as a discretization of the gravity sum',r'The notes replace an integral over metrics on the sphere by \(Z(\beta)=\sum_n\sum_{\Gamma_n}e^{-\beta n}\), allowing generalized triangulations, and say forbidding exceptional gluings does not change the answer.',r'For a specified finite class of connected oriented maps dual to cubic ribbon graphs, define a formal area-generating series with symmetry weights \(1/|\operatorname{Aut}\Gamma|\). Changes between unrestricted maps and simple triangulations alter coefficients and the critical coupling; in the pure-gravity universality class their leading susceptibility exponent agrees. This does not construct a measure on all smooth metrics.',r'\citet[Secs. 2 and 4]{brezinitzyksonparisizuber1978planar} already derive the planar generating series. The continuum gravity interpretation is developed in \citet{polyakov1981quantum}; no equality of measures is proved in these notes.',['brezinitzyksonparisizuber1978planar','polyakov1981quantum'],reconstruction=r'Orientation, connectedness, symmetry weights, and the distinction between exact coefficients and a universal exponent are supplied editorially.',publication_match='partial')
item(682,'P001299','construction','Formal cubic Hermitian matrix integral',r'\(I(g)=\int e^{-\operatorname{tr}(U^2+gU^3/\sqrt N)}dU\), followed by \(Z=\lim N^{-2}\log I(e^{-\beta/2})\).',r'Expand the cubic exponential formally against a normalized Gaussian measure and use \(N^{-2}\log[I(g)/I(0)]\) for connected vacuum graphs. For real nonzero \(g\), the displayed real integral diverges along one scalar direction. A convergent complex-contour definition requires additional data and is not implied by the formal power series.',r'\citet[Sec. 4, Eq. (42)]{brezinitzyksonparisizuber1978planar} explicitly states the instability of the cubic integral and uses its formal series. The notebook suppresses both this qualification and Gaussian normalization.',['brezinitzyksonparisizuber1978planar'],literal_correctness='false as written',reconstruction=r'The formal interpretation and division by \(I(0)\) repair the displayed expression; they are not extra claims attributed to Kazakov.',development='annotated')
item(682,'P001299-P001300','method','Wick contractions and the genus power of N',r'A six-factor Gaussian moment is illustrated by one contraction; double lines make closed index loops contribute \(N\), and a graph is assigned \(N^{F-V/2}=N^{2-2\chi}\), with \(\chi\) called its Euler number.',r'For a Gaussian Hermitian matrix with density proportional to \(e^{-\operatorname{tr}U^2/2}\), \(\mathbb E(U_{ij}U_{kl})=\delta_{il}\delta_{jk}\); every even moment sums over all pairings. A connected cubic ribbon graph has \(3V=2E\), so its power is \(N^{F-E+V}=N^{2-2g}\), where \(g\) is genus. With density \(e^{-\operatorname{tr}U^2}\), the covariance has an additional factor \(1/2\).',r'The topological expansion is the pre-existing large-\(N\) method of \citet{thooft1974planar}; \citet[Sec. 2]{brezinitzyksonparisizuber1978planar} specializes it to matrix counting.',['thooft1974planar','brezinitzyksonparisizuber1978planar'],literal_correctness='false as written',reconstruction=r'The missing pairing sum, index order, Gaussian scaling, and genus/Euler-characteristic distinction are explicit editorial repairs.',development='annotated')
item(682,'P001300','method','Eigenvalue reduction and the Vandermonde square',r'Writing \(U=\Omega\Lambda\Omega^{-1}\) changes the matrix integral into an eigenvalue integral with \(\prod_{i<j}(\lambda_i-\lambda_j)^2\).',r'Lebesgue measure on complex Hermitian matrices decomposes, away from repeated eigenvalues, as \(C_N\Delta(\lambda)^2\prod_i d\lambda_i\,d\bar\Omega\), with angular measure on \(U(N)/U(1)^N\); ordering and permutation factors are absorbed in \(C_N\). For invariant integrands the angular factor cancels in normalized ratios.',r'\citet[Sec. 3]{brezinitzyksonparisizuber1978planar} uses precisely this reduction. It is standard Weyl integration rather than a new matrix-gravity theorem.',['brezinitzyksonparisizuber1978planar'])
item(682,'P001300','remark','Uniform equilibrium density in the circular ensemble',r'Dyson\textquotesingle s circular ensemble is mentioned as a case in which the limiting density is constant.',r'For Haar-distributed unitary matrices the empirical eigenangle measure tends to normalized Lebesgue measure on the circle. This concerns the circular ensemble with no external potential; the Hermitian cubic model has a nonconstant equilibrium density.',r'Dyson\textquotesingle s circular ensembles predate the talk; the notebook uses the comparison to motivate eigenvalue-density methods. The exact source used by the speaker is not identified.',['dyson1962statistical'],verification='publisher metadata checked',publication_match='partial',confidence='medium')
item(682,'P001300-P001301','method','Planar saddle equation and one-cut resolvent',r'The rescaled eigenvalues satisfy \(2\lambda_i+3g\lambda_i^2=2\sum_{j\ne i}(\lambda_i-\lambda_j)^{-1}\). A density of total mass two and an analytic resolvent are introduced.',r'After \(U=\sqrt N M\), the saddle equation is \(V^{\prime}(\lambda_i)=\frac2N\sum_{j\ne i}(\lambda_i-\lambda_j)^{-1}\). If \(\nu=2\rho\), then \(\int\nu=2\), \(V^{\prime}(x)=\operatorname{PV}\int\nu(y)/(x-y)\,dy\), and \(R(z)=\int\nu(y)/(z-y)\,dy\sim2/z\). On a one-cut branch the polynomial-times-square-root ansatz is fixed by these conditions. Boundary values satisfy \(R_+-R_-=-2\pi i\nu\).',r'\citet[Sec. 4, Eqs. (43)--(46)]{brezinitzyksonparisizuber1978planar} gives the cubic solution. The asymptotic condition selects the formal branch analytic near zero coupling; it does not justify an unstable real equilibrium problem.',['brezinitzyksonparisizuber1978planar'],literal_correctness='false as written',reconstruction=r'The \(1/N\), principal value, boundary-value factor \(i\), and specified formal branch are supplied.',development='annotated')
item(682,'P001302','theorem','Exact cubic free-energy series and critical radius',r'The notes give \(-\frac12\sum_{k\ge1}(72g^2)^k\Gamma(3k/2)/[\Gamma(k/2+1)(k+2)!]\), then write \(g_c=1/(108\sqrt3)\).',r'In the source normalization \(\operatorname{tr}(U^2/2+gU^3/\sqrt N)\), the negative planar logarithm has the displayed series and its nearest singularity in \(g^2\) is \(g_c^2=1/(108\sqrt3)\). The notebook\textquotesingle s earlier quadratic coefficient is different, so one must either restore \(U^2/2\) or rescale \(g\). The coefficients are weighted connected maps with \(2k\) cubic vertices.',r'\citet[Sec. 4, Eqs. (49)--(52)]{brezinitzyksonparisizuber1978planar} is an exact pre-1986 match, including the squared critical coupling.',['brezinitzyksonparisizuber1978planar'],literal_correctness='false as written',reconstruction=r'Normalization is compared to the original paper; the series cannot simultaneously use the notebook\textquotesingle s unrescaled quadratic term and the source\textquotesingle s critical constant.',development='annotated')
item(682,'P001302','claim','Pure-gravity singular exponent and map asymptotics',r'\(Z(\beta)\sim(\beta-\beta_c)^{5/2}\) and map coefficients have an \(n^{-7/2}\) factor.',r'The nonanalytic part of the unrooted connected planar free energy has exponent \(5/2\). Transfer to coefficients gives a \(k^{-7/2}\) power multiplying exponential growth, with vertex parity and coupling conventions retained. Analytic background terms are present; rooting a map changes the power by a factor proportional to its number of edges.',r'The cubic solution in \citet[Sec. 4]{brezinitzyksonparisizuber1978planar} supplies this singularity. Record 695 clarifies why unlabelled integer counts are not the coefficients of the raw free energy.',['brezinitzyksonparisizuber1978planar'],publication_match='partial',reconstruction=r'The words nonanalytic part, weighted unrooted count, and parity qualification are editorially necessary.')
item(682,'P001302','remark','Adding spins to the random surface',r'The final paragraph proposes putting a second kind of variable, including spins, on the triangulation.',r'The annealed partition function sums both over maps and over matter configurations on each map. An Ising field on a cubic dual graph can be encoded by two matrix species with a covariance coupling different spins.',r'Kazakov develops this construction in record 685 and in \citet{kazakov1986ising}; no independently specified conjecture occurs in this closing remark.',['kazakov1986ising'],cls='A',publication_match='partial',verification='publisher metadata checked',present_status=r'As of 12 November 2026 the Ising-on-random-map model is solved in the planar limit; this does not identify every possible added matter system.')
corr('P001299-P001302','Matrix-model normalization','Quadratic term U^2, followed by the standard 72g^2 series','Use U^2/2 for the displayed standard series, or rescale g consistently.','Comparison with BIPZ (1978), Eqs. (42), (51), (52); these are mathematical normalization repairs, not asserted paleographic corrections.')
corr('P001302','Critical coupling','g_c=1/(108 sqrt(3))','g_c^2=1/(108 sqrt(3)), in the BIPZ quadratic normalization.','BIPZ (1978), Eq. (52) explicitly gives g_c squared.')
save()

talk(683,'1986-09-29','V. Yu. Ovsienko','P001297-P001304','KdV and super-KdV as Euler equations',r'The mathematical report occupies only the middle of P001298, between Ginzburg\textquotesingle s Hecke-algebra discussion and Kazakov\textquotesingle s random surfaces. It identifies KdV and its supersymmetric extensions with Euler equations for Virasoro-type groups; the catalogue\textquotesingle s wide page range does not transfer adjacent talks to Ovsienko.')
item(683,'P001298','theorem','KdV as the Euler equation on the Virasoro group',r'KdV is described as an Euler equation on the Virasoro group, extending the familiar Euler equation for a Lie group.',r'For the Virasoro central extension of vector fields on the circle, the Euler--Arnold equation of the right-invariant \(L^2\) metric is, up to choices of signs and scale, \(u_t+3uu_x+c u_{xxx}=0\). The fixed dual central coordinate produces dispersion; the metric and coadjoint convention are indispensable.',r'\citet{ovsienkokhesin1987super} describes the known Virasoro Euler construction before giving the super-extension. Its manuscript was received 8 August 1986 and published in 1987.',['ovsienkokhesin1987super'],reconstruction=r'The metric, fixed central coordinate, and coefficient convention are supplied rather than read from the one-line note.',publication_match='partial')
item(683,'P001298','construction','Euler equations on the Neveu--Schwarz and Ramond superalgebras',r'The report adds the supersymmetric KdV equations and names the Schwarz and Ramond algebras.',r'Using the invariant variational pairing on the even and odd components of the Neveu--Schwarz or Ramond algebra yields a super Euler equation. The distinction is the half-integral versus integral indexing of odd modes; an odd variable is Grassmann-valued, so its products cannot be replaced by commuting scalar functions.',r'\citet{ovsienkokhesin1987super}, received 8 August 1986 and published in Functional Analysis and Its Applications 21(4), gives the directly matching construction.',['ovsienkokhesin1987super'],cls='A',reconstruction=r'The name Neveu--Schwarz and the parity conventions expand the notebook shorthand. No explicit component system is preserved in this occurrence.',publication_match='partial')
save()

talk(684,'1986-09-29','V. L. Ginzburg','P001302-P001305','Generalized Lie algebras: manuscript attribution to D. Gurevich',r'The catalogue identifies Ginzburg on 29 September. The original heading on P001303 instead reads D. Gurevich, 13 October 1986, followed by generalized Lie algebras and groups. We retain the catalogue record but attribute the surviving mathematical items explicitly to D. I. Gurevich. They concern involutive Yang--Baxter operators, braided Lie identities, super and color examples, and braided commutators. Kazakov begins later on P001304.')
item(684,'P001303','definition','An involutive Yang--Baxter symmetry',r'A linear map \(S:L\otimes L\to L\otimes L\) satisfies \(S^2=1\) and \(S_1S_2S_1=S_2S_1S_2\).',r'Let \(L\) be finite-dimensional over a characteristic-zero field. An involution \(S\) satisfying the braid equation determines representations of every symmetric group on \(L^{\otimes n}\), by acting in adjacent tensor factors; dropping involutivity gives braid-group representations.',r'\citet[pp. 797--799]{gurevich1986yangbaxter} introduced this generalized formal Lie-theoretic framework before the manuscript talk: the note was received 10 April 1985 and published in 1986.',['gurevich1986yangbaxter'],speaker='D. I. Gurevich',literal_correctness='correct')
item(684,'P001303','definition','Braided antisymmetry, Jacobi identity, and bracket covariance',r'Three identities for the bracket are given in right-acting operator notation: antisymmetry, a three-term Jacobi identity, and a compatibility relation with \(S\).',r'In a symmetric monoidal category with symmetry \(S\), a Lie object has a morphism \(b:L\otimes L\to L\) satisfying \(bS=-b\) and the categorical Jacobi identity. On ordinary vector spaces the further compatibility that \(b\) is a morphism for the specified tensor symmetry is essential; a bare pair consisting of any Yang--Baxter operator and any antisymmetric bracket is insufficient.',r'\citet[pp. 798--800]{gurevich1986yangbaxter} states the corresponding generalized Lie identities. The notebook is a compressed exposition of that theory, not an independent new axiom system.',['gurevich1986yangbaxter'],speaker='D. I. Gurevich',reconstruction=r'The categorical formulation avoids silently reversing the notebook\textquotesingle s right-acting products; the bracket covariance is retained as a separate hypothesis.')
item(684,'P001303-P001304','construction','Ordinary and super Lie algebras as examples',r'The flip gives ordinary Lie algebras; a signed flip determined by degrees gives superalgebras.',r'For the ordinary flip \(S(x\otimes y)=y\otimes x\) the axioms recover Lie algebras. For a \(\mathbb Z/2\)-graded space, \(S(x\otimes y)=(-1)^{|x||y|}y\otimes x\), with a parity-preserving bracket, gives super antisymmetry and super Jacobi. The degree of a nonzero homogeneous bracket is \(|x|+|y|\) modulo two.',r'These are the foundational examples recalled in \citet[pp. 798--799]{gurevich1986yangbaxter}; Lie superalgebras were already established well before 1986.',['gurevich1986yangbaxter'],speaker='D. I. Gurevich',reconstruction=r'Additivity of parity is a condition on homogeneous brackets, not a definition of the bracket of arbitrary nonhomogeneous vectors.')
item(684,'P001304','construction','Color symmetries and color brackets',r'\(S(t_i\otimes t_j)=a(i,j)t_j\otimes t_i\), with conditions on \(a\) said to follow from the axioms; the notes cite Trostel, Journal of Mathematical Physics 25(11), 1984.',r'For an abelian grading group \(G\), a bicharacter \(\varepsilon:G\times G\to k^\times\) satisfying \(\varepsilon(g,h)\varepsilon(h,g)=1\) defines such an involutive symmetry. A homogeneous bracket of degree zero then satisfies \(\varepsilon\)-skew symmetry and the corresponding color Jacobi identity. Arbitrary coefficients \(a(i,j)\) need compatibility with the degrees and nonzero structure constants.',r'The notebook citation is identifiable as \citet{trostel1984color}, pp. 3183--3189. The publisher metadata matches the year, volume, issue, and subject; it does not establish the uncertain attribution to Mosolov elsewhere in the line.',['trostel1984color','gurevich1986yangbaxter'],speaker='D. I. Gurevich',verification='publisher metadata checked',publication_match='partial',reconstruction=r'The grading group and bicharacter supply one standard precise realization of the displayed coefficients; the notes do not specify them.',confidence='medium')
item(684,'P001304','construction','The braided commutator of an associative algebra',r'An associative algebra produces a generalized Lie bracket by subtracting the product with reversed factors through \(S\).',r'If \((A,\mu)\) is an associative algebra object in the symmetric tensor category defined by an involutive braiding \(S\), then \(b=\mu-\mu S\) is a Lie object. Associativity alone, combined with an unrelated solution of the braid equation, does not suffice: multiplication must be compatible with the braiding.',r'\citet[pp. 799--800]{gurevich1986yangbaxter} treats associative and Lie objects in the same compatible setting.',['gurevich1986yangbaxter'],speaker='D. I. Gurevich',reconstruction=r'The compatibility hypothesis is explicit in the modern statement; the brief notebook sentence leaves it implicit.')
item(684,'P001304','remark','Historical attribution of braiding formalism to Drinfeld',r'The notes say that Drinfeld put braids in their final form.',r'This sentence records a historical assessment; it does not specify a theorem, construction, or priority claim precise enough to adjudicate. The mathematical identities actually present are indexed separately.',r'Gurevich\textquotesingle s 1986 paper provides a concrete contemporaneous source for the adjacent mathematics, but no exact publication is identified with this informal phrase.',['gurevich1986yangbaxter'],cls='F',speaker='D. I. Gurevich',literal_correctness='not determinable',publication_match='thematic only',confidence='low',present_status=r'As of 12 November 2026 the phrase remains an insufficiently specified historical attribution; no open mathematical problem is inferred.')
corr('P001303','Talk heading and catalogue attribution','Catalogue: V. L. Ginzburg, 29 September 1986','Manuscript: D. Gurevich, 13 October 1986. Preserve catalogue metadata and explicitly attribute the surviving items.','Original scan viewed: handwritten heading and date are clear; generalized Lie algebra content matches Gurevich (1986).',typ='provenance')
save()

talk(685,'1986-09-29','V. A. Kazakov','P001303-P001308','Ising spins on random triangulations and Wick expansion',r'The catalogue date is preserved, but this exposition begins after the Gurevich heading dated 13 October and occupies P001304--P001306. It introduces annealed Ising gravity, a two-matrix representation, a critical temperature, and a Wick-theorem intervention by A. N. Varchenko. Ginzburg\textquotesingle s braid discussion starts with the next dated heading and is not part of this record.')
item(685,'P001304-P001305','construction','Annealed Ising model on cubic planar maps',r'Spins \(\sigma_i=\pm1\) are summed on the vertices of a random dual graph, with edge interaction and magnetic field.',r'For each connected cubic map \(\Gamma\), use \(Z_\Gamma(\beta,H)=\sum_{\sigma}\exp[\beta\sum_{\{i,j\}\in E}\sigma_i\sigma_j+H\sum_i\sigma_i]\), then sum over maps with a specified area and automorphism weight. Each unoriented edge is counted once. This is an annealed ensemble: summing over geometry is part of the partition function.',r'\citet{kazakov1986ising}, published December 1986, exactly solves a closely related planar Ising matrix model. \citet{boulatovkazakov1987ising} develops the magnetic-field critical behavior; its preprint circulated in 1986.',['kazakov1986ising','boulatovkazakov1987ising'],cls='A',publication_match='partial',verification='publisher metadata checked',reconstruction=r'Edge counting and symmetry weights remove otherwise ambiguous factors in the notebook expression.')
item(685,'P001305','claim','Continuum Majorana field coupled to gravity',r'The model is associated with a fermionic field and gravity; the notes emphasize that the continuum identification is difficult.',r'The critical Ising matter theory is the Majorana conformal field theory with central charge \(1/2\). Its coupling to random planar maps has continuum gravitational critical exponents. A formal identification of a discrete annealed partition sum with a path integral over metrics and Grassmann fields is not, by itself, an equality of rigorously defined measures.',r'The matrix solution of \citet{kazakov1986ising} and its extension in \citet{boulatovkazakov1987ising} establish exact discrete planar results; their interpretation as matter coupled to gravity is a further continuum argument.',['kazakov1986ising','boulatovkazakov1987ising'],cls='A',publication_match='partial',verification='publisher metadata checked',reconstruction=r'The central charge and the distinction between discrete exact solvability and continuum measure construction are editorial context.',present_status=r'As of 12 November 2026 the Ising-gravity universality class and its exponents are established; the notebook supplies no precise measure-convergence theorem to classify separately.')
item(685,'P001305','construction','Two-matrix encoding of Ising edge weights',r'The integral has a mixed quadratic term \(-2cUV\) and cubic terms \(g(e^HU^3+e^{-H}V^3)/\sqrt N\), with \(c=e^{-2\beta}\).',r'Use two Hermitian Gaussian matrices with covariance proportional to \(\begin{pmatrix}1&c\\c&1\end{pmatrix}\), for \(|c|<1\), and expand the cubic terms formally. A propagator between different species carries weight \(c\) relative to equal species. Multiplication by a common edge factor converts this to \(e^{\beta\sigma_i\sigma_j}\). Cubic integrals on a real contour remain formal unless contours are specified.',r'This is the matrix-model mechanism of \citet{kazakov1986ising} and \citet{boulatovkazakov1987ising}. A quartic model enumerates maps of a different valency and has different critical couplings.',['kazakov1986ising','boulatovkazakov1987ising'],cls='A',publication_match='partial',verification='publisher metadata checked',reconstruction=r'The covariance, positivity restriction, and common edge rescaling are supplied; the notebook uses an unnormalized quadratic form.')
item(685,'P001305','theorem','Critical Ising coupling on cubic random maps',r'The transition is at \(\beta_*=\frac12\log(2\sqrt7+1)\).',r'For the standard cubic two-matrix Ising model at zero magnetic field, the matter critical point has \(c_*=e^{-2\beta_*}=(2\sqrt7-1)/27=1/(2\sqrt7+1)\). This is a joint critical point of matter and the map-generating function, not the fixed square-lattice Ising temperature.',r'The cubic critical constant is checked against the explicit Boulatov--Kazakov model in \citet[Eq. (4.4)]{sato2020ising}; its antecedent is \citet{boulatovkazakov1987ising}. The 1986 quartic-lattice paper alone is not an exact match for this numerical constant.',['sato2020ising','boulatovkazakov1987ising'],cls='A',publication_match='exact',reconstruction=r'The zero-field cubic-map normalization is necessary to identify the constant.')
item(685,'P001305-P001306','theorem','Wick theorem as an all-pairings identity',r'Varchenko explains that the Gaussian moment is the sum of products of pairwise covariances; odd moments vanish.',r'For centered jointly Gaussian variables \(X_1,\ldots,X_{2m}\), \(\mathbb E\prod_iX_i=\sum_{\pi}\prod_{\{a,b\}\in\pi}\mathbb E(X_aX_b)\), where \(\pi\) runs over all perfect matchings; moments of odd total degree are zero. Repeated variables are allowed. The matrix version is obtained by substituting its covariance.',r'This is the classical Gaussian pairing theorem used by \citet[Sec. 2]{brezinitzyksonparisizuber1978planar}. The intervention explains the mechanism rather than proposes a new theorem.',['brezinitzyksonparisizuber1978planar'],speaker='A. N. Varchenko',literal_correctness='correct')
item(685,'P001306','method','Expansion coefficients and Gaussian index contraction',r'The expansion is written with Gaussian moments of powers of traces; the displayed contractions and Taylor coefficients are compressed.',r'The formal identity is \(\langle e^{-gP}\rangle_0=\sum_{n\ge0}(-g)^n\langle P^n\rangle_0/n!\). Hermitian entry contractions cross the indices, \(\langle U_{ij}U_{kl}\rangle_0\propto\delta_{il}\delta_{jk}\). Logarithms select connected diagrams, with automorphism weights remaining after the factorials are included.',r'\citet[Secs. 2--4]{brezinitzyksonparisizuber1978planar} supplies the relevant expansion and graph conventions. These details explain the rational, rather than unlabelled integer, coefficients stressed later in record 695.',['brezinitzyksonparisizuber1978planar'],literal_correctness='false as written',development='annotated',reconstruction=r'Taylor factorials and covariance orientation are restored explicitly; these are repairs to the displayed shorthand.')
corr('P001304-P001306','Date of Kazakov continuation','Catalogue: 29 September 1986','The notes follow the heading dated 13 October 1986; keep the catalogue date and flag the manuscript sequence.','Viewed P001303 heading and checked source continuity into Kazakov section.',typ='provenance')
save()

talk(686,'1986-10-20','V. L. Ginzburg','P001306-P001310','Polynomial monodromy and the Burau representation',r'The actual mathematical section is P001307--P001308. It constructs braid representations from cohomology of a punctured plane, identifies a Hecke relation, and asks faithfulness of Burau. The same letter is used for an exponent and a multiplicative monodromy parameter; the hyperelliptic example makes the ambiguity substantive.')
item(686,'P001307-P001308','construction','Discriminant complements and the braid group',r'Roots are replaced by coefficients \(\sigma_1,\ldots,\sigma_n\); the discriminant is removed, and the fundamental group is identified with the group of braids.',r'The space of monic complex polynomials of degree \(n\) with simple roots is the unordered configuration space of \(n\) points in \(\mathbb C\), hence has fundamental group \(B_n\). The ordered root space is its \(S_n\)-cover and has pure braid group as fundamental group. The universal punctured-plane fibration has fiber \(\mathbb C\setminus\{z_1,\ldots,z_n\}\).',r'The topological construction underlying the Burau representation is recalled in \citet[Sec. 2]{bigelow1999burau}; it was classical before this report.',['bigelow1999burau'],literal_correctness='correct')
item(686,'P001308','construction','Rank-one twisted cohomology and reduced Burau',r'The multivalued function \(f^\alpha\), where \(f(z)=\prod(z-z_i)\), defines coefficients for first cohomology; moving the roots gives a braid representation.',r'Let \(t=e^{2\pi i\alpha}\ne1\) be the common local monodromy about each puncture. Then \(H^1(\mathbb C\setminus\{z_i\},\mathcal L_t)\) has dimension \(n-1\). Monodromy in the configuration space gives the reduced Burau representation, up to duality and basis conventions. The universal form is over \(\mathbb Z[t,t^{-1}]\), and specializing \(t\) is a separate operation.',r'\citet[Sec. 2]{bigelow1999burau} uses the equivalent infinite-cyclic-cover construction. It verifies the representation being discussed, but not the notebook\textquotesingle s attribution of every step to Givental.',['bigelow1999burau'],reconstruction=r'The nontrivial local-monodromy hypothesis and separation of formal parameter from exponent are supplied.',publication_match='partial')
item(686,'P001308','claim','The Hecke quadratic relation and parameter conversion',r'The braid generator is said to satisfy \((T_i+1)(T_i-\alpha)=0\), although \(\alpha\) has just denoted the exponent of \(f\).',r'For the conventional Burau generator \(B_i\), \((B_i-1)(B_i+t)=0\). With \(T_i=-B_i\), this becomes \((T_i+1)(T_i-t)=0\). Thus the Hecke parameter is the multiplicative monodromy \(t\), not the additive exponent \(\alpha\); inverse conventions can replace \(t\) by \(t^{-1}\).',r'The universal representation and its matrices are stated in \citet[Sec. 1]{bharathrambirmanbrendle2026burau}; the notebook\textquotesingle s formula is consistent only after a parameter renaming and sign convention.',['bharathrambirmanbrendle2026burau'],literal_correctness='false as written',development='annotated',reconstruction=r'The displayed polynomial is reconciled by an explicit normalization, not silently copied.')
item(686,'P001308','problem','Faithfulness of the Burau representation',r'The stated goal is to prove faithfulness; the case \(n=3\) is already known.',r'For which \(n\) is the universal reduced Burau representation \(B_n\to\operatorname{GL}_{n-1}(\mathbb Z[t,t^{-1}])\) injective? This concerns the indeterminate-parameter representation and does not assert faithfulness at every complex specialization.',r'\citet[Theorem 1.1]{bigelow1999burau}, first posted 20 April 1999 and published in 1999, proves nonfaithfulness for \(n\ge5\). \citet[Main Theorem, Sec. 1]{bharathrambirmanbrendle2026burau}, posted 6 July and revised 14 September 2026, claims faithfulness for \(n=4\). Its actual theorem and PDF were read; the proof has not been independently certified in this project.',['bigelow1999burau','bharathrambirmanbrendle2026burau'],cls='B',problem='GP-1986-30',literal_correctness='correct',present_status=r'As of 12 November 2026, faithfulness for \(n\le3\) and nonfaithfulness for \(n\ge5\) are established; \(n=4\) has a recent affirmative preprint claim, which must be identified as such. The unrestricted conjecture in the notes is false.',reconstruction=r'The original all-rank question is separated from the exceptional rank-four case and from specialized representations.')
item(686,'P001308','remark','Hyperelliptic monodromy specialization',r'The final line says \(\alpha=-1\) yields monodromy of elliptic or hyperelliptic integrals.',r'The double-cover interpretation corresponds to local monodromy \(t=-1\), hence exponent \(\alpha\in\frac12+\mathbb Z\) if \(f^\alpha\) is used. Its periods lie in the appropriate anti-invariant part of homology of the branched double cover; compactification and parity of the number of branch points affect the dimension.',r'The Burau-cover description in \citet[Sec. 2]{bigelow1999burau} supports the specialization, but the notebook conflates the exponent and its exponential.',['bigelow1999burau'],literal_correctness='false as written',publication_match='partial',development='annotated',reconstruction=r'The distinction between exponent \(-1\), which has trivial monodromy, and multiplicative parameter \(-1\) resolves the apparent contradiction.')
problem('GP-1986-30','Faithfulness of universal Burau representations',r'Determine the ranks \(n\) for which the Burau representation over \(\mathbb Z[t,t^{-1}]\) is faithful.',['1986-686.4'],r'As of 12 November 2026, faithful for \(n\le3\), unfaithful for \(n\ge5\). A July 2026 preprint, revised September 2026, claims faithfulness for \(n=4\); its main theorem was read but not independently checked here.',['bigelow1999burau','bharathrambirmanbrendle2026burau'])
corr('P001308','Exponent versus Hecke parameter','f^alpha; (T+1)(T-alpha)=0; alpha=-1 is hyperelliptic','Write t=exp(2 pi i alpha); the Hecke relation uses t, and the double cover has t=-1.','Original scan viewed: the same handwritten alpha is indeed used in all three positions; this is a faithful mathematical ambiguity, not a mistranscription.',typ='ambiguity')
save()

talk(687,'1986-10-20','A. A. Beilinson','P001308-P001310','The Deligne--Illusie proof of Hodge degeneration',r'The short report at the top of P001309 announces an algebraic proof of degeneration of the Hodge--de Rham spectral sequence, referring to an Orsay preprint by Deligne and Illusie. The theorem over characteristic zero and the new positive-characteristic method are separate items.')
item(687,'P001309','theorem','Hodge--de Rham degeneration in characteristic zero',r'For a smooth projective complex variety, the spectral sequence from coherent differential forms to de Rham cohomology degenerates.',r'For a smooth proper variety \(X\) over a characteristic-zero field, \(E_1^{p,q}=H^q(X,\Omega_X^p)\Rightarrow H_{\mathrm{dR}}^{p+q}(X)\) degenerates at \(E_1\). Over \(\mathbb C\), algebraic de Rham cohomology identifies with singular cohomology with complex coefficients; projective smoothness also supplies the classical Hodge decomposition.',r'The statement predates the seminar. \citet[Introduction and Cor. 2.4]{deligneillusie1987relevements} gives a new algebraic proof through reduction to positive characteristic, published in 1987.',['deligneillusie1987relevements'],literal_correctness='correct',reconstruction=r'The indexing is standardized and smooth proper is distinguished from the more restrictive projective hypothesis in the note.')
item(687,'P001309','method','Lifting modulo p squared and the truncated Cartier splitting',r'The notes credit a new algebraic proof to Deligne and Illusie, with a preprint at Orsay.',r'If \(X\) is smooth over a perfect field of characteristic \(p>0\) and lifts smoothly to \(W_2(k)\), then the truncated Frobenius pushforward \(\tau_{<p}F_*\Omega_X^\bullet\) splits in the derived category as \(\bigoplus_{i<p}\Omega^i_{X^{(1)}}[-i]\). For proper \(X\) with \(\dim X<p\), this yields full Hodge--de Rham degeneration. Characteristic-zero degeneration follows by spreading out and choosing suitable large primes.',r'\citet[Thm. 2.1 and Cor. 2.4]{deligneillusie1987relevements} is the precise matching result. The notebook witnesses circulation by October 1986; the article appeared in Inventiones 89 (1987), 247--270.',['deligneillusie1987relevements'],cls='B',reconstruction=r'The lifting, perfectness, truncation, and dimension hypotheses are not present in the brief report and are reconstructed from the theorem.')
save()

talk(688,'1986-10-20','V. A. Kazakov','P001308-P001312','Unitary orbital integrals and reduced gauge models',r'The section from the lower part of P001309 through P001311 develops the Harish-Chandra--Itzykson--Zuber integral, recalls the principal-minor spherical-function formula, and explains the radial heat operator. It closes with a two-source integral and the Eguchi--Kawai matrix reduction. The final assertion that the reduced integral contains all gauge theory needs a center-symmetry qualification.')
item(688,'P001309-P001310','theorem','The normalized Harish-Chandra--Itzykson--Zuber integral',r'The unitary integral of \(\exp\operatorname{tr}(\Lambda U M U^*)\) is a determinant of exponentials divided by two Vandermondes.',r'For Hermitian \(A,B\) with eigenvalues \(a_i,b_j\) and normalized Haar measure, \[\int_{U(N)}e^{t\operatorname{tr}(AUBU^*)}\,dU=\left(\prod_{k=1}^{N-1}k!\right)t^{-N(N-1)/2}\frac{\det[e^{ta_i b_j}]}{\Delta(a)\Delta(b)}.\] Initially take distinct eigenvalues and \(t\ne0\); all apparent singularities extend by continuity. The same Vandermonde ordering is used in numerator conventions for both spectra.',r'\citet[Eq. (3.12)]{itzyksonzuber1980planar} gives the directly matching matrix formula, building on Harish-Chandra\textquotesingle s earlier orbital-integral work. The author-hosted original PDF and formula were inspected.',['itzyksonzuber1980planar'],literal_correctness='correct with missing hypotheses')
item(688,'P001310','theorem','Principal-minor integral and shifted spherical parameters',r'Gelfand recalls an integral of complex powers of successive principal minors and attributes it to Gelfand--Naimark, 1951.',r'For \(R>0\), principal minors \(\Delta_k\), \(s\in\mathbb C^N\), and \(s_{N+1}=0\), average \(\prod_k\Delta_k(URU^*)^{s_k-s_{k+1}}\). If \(a_j=s_j+N-j\), the value is \(\bigl(\prod_{k=1}^{N-1}k!\bigr)\det[r_i^{a_j}]/[\Delta(r)\Delta(a)]\). Positive minors fix the logarithms; colliding parameters are handled by limits.',r'The old formula and its original book locator are reproduced with proof in \citet[Prop. 2.1]{faraut2014rayleigh}. Record 692 gives a fuller representation-theoretic explanation. The shifts \(N-j\) must not be dropped.',['faraut2014rayleigh'],speaker='I. M. Gelfand',reconstruction=r'The exact principal-minor exponents and Weyl shifts repair the compressed notebook display.',publication_match='partial')
item(688,'P001310-P001311','method','Radial heat operator on Hermitian matrices',r'The heat equation on the real vector space of Hermitian matrices becomes a radial equation in eigenvalues; multiplication by the Vandermonde makes it free.',r'With the Hilbert--Schmidt Euclidean metric on \(\operatorname{Herm}_N\), a conjugation-invariant smooth function has radial Laplacian \(\Delta(\lambda)^{-2}\sum_i\partial_i[\Delta(\lambda)^2\partial_i]\). Conjugation by \(\Delta\) gives \(\Delta^{-1}\sum_i\partial_i^2\Delta\). The radial heat kernel is therefore an antisymmetrized product of scalar Gaussian kernels after accounting for the Jacobian.',r'\citet[Sec. 3, Eqs. (3.13)--(3.17)]{itzyksonzuber1980planar} gives this derivation. It is specific to the complex Hermitian, or Dyson-index-two, radial operator; analogous real and quaternionic operators retain interaction terms.',['itzyksonzuber1980planar'],reconstruction=r'The metric fixes heat-time and Gaussian normalization; smooth continuation through collisions is understood.')
item(688,'P001311','remark','Berezin and Harish-Chandra antecedents of the radial method',r'Gelfand says Berezin had obtained the result and Harish-Chandra used it repeatedly.',r'This intervention links the matrix heat calculation to the radial-part method in harmonic analysis. It does not identify a unique dissertation proposition; the exact unitary integral and its radial proof are indexed separately.',r'\citet{berezingelfand1956spherical} is a verified pre-1986 primary source for spherical-function harmonic analysis. The notebook\textquotesingle s particular dissertation attribution is retained as a historical recollection, not upgraded to a proved priority assertion.',['berezingelfand1956spherical'],speaker='I. M. Gelfand',publication_match='thematic only',verification='publisher metadata checked',confidence='medium',present_status=r'As of 12 November 2026 the mathematical antecedent is established, but the precise dissertation passage intended by this intervention is not identified.')
item(688,'P001311','question','A unitary integral with two coupled external-source pairs',r'The question is to evaluate \(\int e^{\operatorname{tr}(A_1UB_1U^*)+\operatorname{tr}(A_2UB_2U^*)}\,dU\), related in the notes to a chiral field.',r'For fixed finite matrices, the exponential has an absolutely convergent Taylor expansion on the compact group. Each coefficient is a finite sum of unitary moments computable by Weingarten calculus. In general the two-source exponent does not reduce to one HCIZ pair; an all-coupling planar asymptotic formula is a stronger question than finite-dimensional evaluability.',r'\citet[Sec. 2, Cor. 2.4]{collinssniady2006integration}, first circulated February 2004 and published 2006, gives all polynomial Haar moments, hence an exact coefficientwise method. The notebook does not specify the source scaling needed to identify a unique large-\(N\) chiral-field problem.',['collinssniady2006integration'],cls='B',publication_match='partial',reconstruction=r'The convergent finite-\(N\) method is an editorial application of the integration theorem; it is not asserted to be the speaker\textquotesingle s intended closed formula.',present_status=r'As of 12 November 2026 finite-\(N\) evaluation by a convergent moment series is available. The vague chiral-field identification is not treated as a separate solved or open theorem.')
item(688,'P001311','construction','Eguchi--Kawai reduction and its symmetry hypothesis',r'The integral over \(d\) unitary matrices with plaquette terms is called the lattice Yang--Mills partition function, containing all \(d\)-dimensional physics.',r'The one-site action is \(N\beta\sum_{\mu<\nu}\operatorname{Re}\operatorname{tr}(U_\mu U_\nu U_\mu^*U_\nu^*)\), up to normalization. Equality of planar Wilson-loop equations with an extended lattice requires large-\(N\) factorization, unbroken center symmetry, and translation invariance in the unreduced model. The untwisted bosonic one-site model breaks center symmetry at weak coupling in four dimensions, so the literal universal equivalence fails.',r'\citet{eguchikawai1982reduction} proposes the reduction. \citet[Sec. 2]{garciaperez2020largeN} states the exact symmetry conditions and explains the original failure; twisted, deformed, and adjoint-fermion variants are distinct models.',['eguchikawai1982reduction','garciaperez2020largeN'],literal_correctness='false as written',publication_match='partial',development='annotated',reconstruction=r'The factor of \(N\), real part, and symmetry conditions are supplied. Oppositely oriented terms in the notebook can themselves make the action real.')
item(688,'P001311','problem','Analytic solution of reduced planar gauge integrals in dimensions three and four',r'The integral is underlined as unevaluated, and gauge theory as unsolved.',r'Determine the large-\(N\) free energy and Wilson-loop observables of a precisely normalized \(d\)-matrix reduced gauge model for \(d=3,4\), through its phases, and establish the regime in which these observables reproduce the extended-lattice theory. Solving a finite compact integral by Taylor expansion is not this nonperturbative planar problem.',r'The reduction of \citet{eguchikawai1982reduction} is a reformulation, not a general analytic solution. \citet[Secs. 1--2]{garciaperez2020largeN} describes continuing numerical work; \citet{neuberger2020quenched} distinguishes competing quenching prescriptions. Neither proves an all-coupling solution of the notebook integral.',['eguchikawai1982reduction','garciaperez2020largeN','neuberger2020quenched'],cls='C',problem='GP-1986-31',publication_match='partial',worth=r'Worth developing only after fixing a model and phase; a bounded strong-coupling coefficient calculation or symmetry test is feasible, whereas an all-coupling solution is not a bounded project.',present_status=r'As of 12 November 2026 exact two-dimensional results and controlled reductions/numerics do not provide the requested general three- or four-dimensional planar solution. The original untwisted weak-coupling equivalence is false, and must be repaired before a continuum-physics claim.',reconstruction=r'The free-energy scaling, observables, and distinction between the unrepaired original model and symmetry-preserving variants make the question precise.')
problem('GP-1986-31','Three- and four-dimensional reduced planar gauge models',r'For a specified one-site unitary plaquette model, determine its nonperturbative planar free energy and Wilson loops, with the center-symmetry conditions needed for volume reduction made explicit.',['1986-688.7'],r'As of 12 November 2026 the general all-coupling planar solution is unavailable in the sources checked; exact two-dimensional reductions and higher-dimensional numerical methods are established. Unconditional equivalence of the original untwisted model with four-dimensional weak-coupling gauge theory is false.',['eguchikawai1982reduction','garciaperez2020largeN','neuberger2020quenched'])
save()

talk(689,'1986-10-27','I. S. Zakharevich','P001310-P001313','Orbital integration, interlacing, and concentration remarks',r'The new dated heading begins at P001312. The report revisits the orbital-integral heat proof and the spectral distribution of products of positive matrices, then uses sections of ellipsoids and interlacing arrays. Gelfand adds two high-dimensional intuition questions. Their printed numerical and dynamical assertions require separate qualifications.')
item(689,'P001312','method','Heat-kernel proof of the unitary orbital formula',r'The report starts from \(g_t=\Delta g\) on Hermitian matrices and states the determinant formula for the orbital integral.',r'Compare the full Euclidean heat kernel on \(\operatorname{Herm}_N\) with its radial kernel after multiplication by \(\Delta(\lambda)\). Antisymmetrization over eigenvalue permutations yields the determinant of scalar heat kernels and therefore HCIZ, normalized by the value at a scalar matrix.',r'This is the method already given in \citet[Sec. 3]{itzyksonzuber1980planar}; it repeats 1986-688.3 with a new exposition.',['itzyksonzuber1980planar'],literal_correctness='correct')
item(689,'P001312','question','Spectrum of a product of positive Hermitian matrices',r'Given the spectra of \(H_1,H_2>0\), the notes ask how the spectrum of \(H_1H_2\) is distributed.',r'The product is similar to \(H_1^{1/2}H_2H_1^{1/2}>0\). Two different questions must be distinguished: which eigenvalue lists occur, and the pushforward distribution when relative eigenvectors have Haar law. The first is a multiplicative spectral-support problem; the second needs a specified measure and cannot be answered by support inequalities alone.',r'\citet{klyachko2000random} relates product singular-value support to additive Hermitian spectral inequalities. Principal-minor spherical transforms, as in \citet[Sec. 2]{faraut2014rayleigh}, are relevant to the distribution question. Neither reference is claimed to be the exact unstated density formula intended in the note.',['klyachko2000random','faraut2014rayleigh'],cls='B',publication_match='partial',verification='publisher metadata checked',reconstruction=r'Haar-relative-eigenbasis sampling is supplied as the natural precise probabilistic interpretation; the note does not explicitly choose it.',present_status=r'As of 12 November 2026 finite-dimensional spectral support has established solutions; the notebook\textquotesingle s unspecified distribution question is not identified with one universal density theorem.',confidence='medium')
item(689,'P001312','theorem','Ellipsoid sections and interlacing arrays',r'A plane section of an ellipsoid with axes \(a,b,c\) is described by \(a\le a_1\le b\le b_1\le c\); repeated sections form a triangular array.',r'For a Hermitian operator restricted orthogonally to a codimension-one subspace, sorted eigenvalues interlace. Repeated principal compressions produce Gelfand--Tsetlin patterns. For ellipsoids, the quadratic-form eigenvalues are inverse squared semiaxes; the inequality must be translated consistently if the symbols denote geometric lengths.',r'\citet[Thm. 1.1 and Prop. 2.3]{faraut2014rayleigh} states the interlacing theorem and orbital-measure pushforward. The geometric interlacing is classical; the modern probability formulation is context, not a 1986 novelty attribution.',['faraut2014rayleigh'],reconstruction=r'Compression, axis convention, and ordering are supplied.')
item(689,'P001312','method','Principal-minor powers as spherical coordinates for integration',r'The next integral averages powers of \(a_{11}\), a leading \(2\times2\) determinant, and successive minors of \(U^*\mu U\).',r'For positive definite \(\mu\), these complex powers are unambiguously defined using positive real logarithms. Their unitary average is the spherical function of \(\operatorname{GL}_N(\mathbb C)/U(N)\); the exponent differences and \(N-j\) shifts are as in 1986-688.2 and 1986-692.1.',r'\citet[Sec. 2, Prop. 2.1]{faraut2014rayleigh} reproduces the Gelfand--Naimark integration scheme. This occurrence motivates the representation-theoretic explanation given on 3 November.',['faraut2014rayleigh'],reconstruction=r'Positivity of \(\mu\) is needed for the elementary complex-power interpretation.')
item(689,'P001312','claim','The numerical equatorial-slab assertion in dimension 1000',r'The question asks what fraction of a 1000-dimensional ball lies in a layer of thickness \(R/100\) about an equator; the answer written is almost all.',r'For uniform volume in the radius-\(R\) ball of dimension \(d\), \(\Pr(|x_1|\le aR)=I_{a^2}(1/2,(d+1)/2)\). At \(d=1000\), even the generous half-width interpretation \(a=0.01\) gives approximately \(0.248\); interpreting \(R/100\) as total thickness gives approximately \(0.126\). Thus the literal numerical example does not illustrate almost-full concentration.',r'The formula follows from the cross-sectional volume of a ball. \oursComputed\ The numerical values are independently checked by quadrature and the regularized beta function in the accompanying code; this is an editorial correction, not a new concentration theorem.',[],literal_correctness='false as written',publication_match='none found',development='annotated',reconstruction=r'Two possible meanings of thickness are tested rather than choosing one silently.',present_status=r'As of 12 November 2026 the general concentration heuristic is standard, but this specific dimension-to-width ratio is quantitatively false.')
item(689,'P001313','claim','Time spent near faces of a high-dimensional simplex billiard',r'A particle reflects at faces of a 1000-dimensional simplex; the notes say it spends almost all time within \(1/100\) of the faces.',r'The statement does not specify units for the boundary layer, the shape or inradius of the simplex, initial-condition measure, or whether the assertion is an ensemble or almost-every-trajectory limit. Concentration of volume near a boundary alone cannot establish a time-average claim without a suitable dynamical hypothesis.',r'No definite billiard theorem can be matched to these missing quantifiers. The neighboring ball question explains the heuristic motivation, but supplies neither ergodicity nor a trajectorywise argument.',[],cls='F',literal_correctness='not determinable',publication_match='none found',verification='unresolved lead',confidence='low',reconstruction=r'The required data are identified without replacing the notebook sentence by an invented general billiard conjecture.',present_status=r'As of 12 November 2026 this occurrence is underdetermined; no open problem or class-D inference is made.')
corr('P001312','1000-dimensional equatorial layer','Thickness R/100 contains almost all volume','About 0.126 for full thickness R/100, or about 0.248 for half-width R/100.','Russian transcription explicitly flags R/100 as manuscript reading; direct cross-sectional integral and beta-function check are saved in code/check_slab.py.',typ='faithful_error')
save()

talk(690,'1986-10-27','B. V. Lidskii','P001311-P001314','The diagonal moment map',r'The short intervention occupies the middle of P001313. It identifies the diagonal projection on a unitary orbit as a moment map and relates its Fourier transform to the orbital integral. The uncertain handwritten initial is not used to override the catalogue identification. Gelfand\textquotesingle s question about a super analogue of the symmetric group follows.')
item(690,'P001313','construction','Diagonal projection as a moment map and its Fourier transform',r'On Hermitian matrices with fixed eigenvalues, take \(H\mapsto\operatorname{diag}H\); the Fourier transform is written down.',r'On the coadjoint orbit of \(U(N)\) with its Kirillov--Kostant--Souriau form, diagonal projection is the moment map for the diagonal torus. Its image is the convex hull of permutations of the fixed eigenvalue list. The Fourier transform of the pushed-forward normalized orbital measure is \(\int e^{i\operatorname{tr}(D U\Lambda U^*)}\,dU\), hence HCIZ with \(t=i\).',r'\citet{duistermaatheckman1982variation} supplies the general moment-map measure context; \citet[Sec. 3]{itzyksonzuber1980planar} supplies the explicit Fourier integral. These were pre-existing results.',['duistermaatheckman1982variation','itzyksonzuber1980planar'],reconstruction=r'The symplectic form, measure normalization, and Schur--Horn image describe the standard precise construction; the note only states the map and transform.',publication_match='partial')
item(690,'P001313','question','What is the super analogue of the symmetric group?',r'Gelfand asks \ru{Что такое супераналог симметрической группы?}',r'No criterion for analogue is specified: permutation action on super tensor powers, a Schur--Weyl centralizer, a spin double cover, and a Lie-superalgebra Weyl object give different answers. The signed permutation action is already present in 1986-684.3, but does not uniquely answer this broader question.',r'The neighboring color-symmetry exposition and \citet{gurevich1986yangbaxter} provide relevant context only. The phrase does not determine a precise research problem or a unique later theorem.',['gurevich1986yangbaxter'],cls='F',speaker='I. M. Gelfand',literal_correctness='not determinable',publication_match='thematic only',confidence='low',present_status=r'As of 12 November 2026 the intended notion remains unidentified from this occurrence; no claim of an undeveloped idea is made.')
save()

talk(691,'1986-10-27','V. L. Ginzburg','P001312-P001315','Exact stationary phase and localization',r'The lower part of P001313 gives an approximate Duistermaat--Heckman formula, its coadjoint-orbit example, and Gelfand\textquotesingle s questions about higher asymptotic terms and characteristic numbers. A final conjectural sentence is explicitly marked mine by the note-taker; it must not be attributed to Gelfand or Ginzburg.')
item(691,'P001313','theorem','Exact stationary phase for a Hamiltonian circle action',r'For a closed symplectic manifold and periodic Hamiltonian flow, the first stationary-phase term is said to give the exact integral. The written prefactor is \((2\pi)^{-n}\), without a signature phase.',r'Let \((M^{2n},\omega)\) be compact without boundary and let \(H\) generate a circle action with isolated fixed points. With Liouville measure \(\omega^n/n!\), the oscillatory integral is exactly its stationary-phase sum. In local Darboux coordinates, for real \(t>0\), each point contributes \((2\pi/t)^n e^{itH(p)}e^{i\pi\operatorname{sgn}(\operatorname{Hess}_pH)/4}/\sqrt{|\det\operatorname{Hess}_pH|}\). Consistent orientation and moment-map conventions fix signs.',r'\citet{duistermaatheckman1982variation} proves exactness; \citet[Thm. (1.5)]{duistermaatheckman1983addendum} treats nonisolated fixed sets. The notebook calls its own formula approximate, appropriately, but its displayed constant and phases cannot be retained literally.',['duistermaatheckman1982variation','duistermaatheckman1983addendum'],literal_correctness='false as written',development='annotated',reconstruction=r'Isolated nondegenerate fixed points, the Liouville factorial, absolute determinant, signature phase, and \(t\)-scaling are supplied.')
item(691,'P001313','construction','Coadjoint-orbit symplectic form and the unitary integral',r'For \(X=U^*\mu U\), the form is written \(\omega(X)(\xi,\eta)=\operatorname{tr}(X[\xi,\eta])\), with \(\xi,\eta\) called tangent vectors.',r'If tangent vectors are represented by infinitesimal generators \(\xi,\eta\) as \(\operatorname{ad}^*\xi X,\operatorname{ad}^*\eta X\), the orbit form is \(\omega_X(\operatorname{ad}^*\xi X,\operatorname{ad}^*\eta X)=\langle X,[\xi,\eta]\rangle\), up to a uniform sign. It descends modulo the stabilizer; generators are not literally arbitrary tangent matrices. A regular unitary orbit is \(U(N)/U(1)^N\); repeated eigenvalues enlarge the stabilizer.',r'This is the orbit example of exact localization in \citet{duistermaatheckman1982variation}; the resulting alternating exponential sum agrees with HCIZ in \citet{itzyksonzuber1980planar}.',['duistermaatheckman1982variation','itzyksonzuber1980planar'],reconstruction=r'The generator/tangent distinction and regular-orbit qualification repair the notation.')
item(691,'P001313','question','Higher stationary-phase terms and characteristic numbers',r'Gelfand asks when the second term vanishes, when the first term is exact, and how characteristic numbers can arise.',r'Within compact Hamiltonian torus geometry, localization on a fixed component integrates the exponential of the restricted symplectic form divided by the equivariant Euler class of its normal bundle. Curvature expansions produce characteristic classes and a finite-degree contribution on each component. Outside a specified Hamiltonian phase-amplitude class, vanishing of one coefficient does not characterize exactness.',r'\citet[Thm. (1.5) and its expansion on pp. 154--155]{duistermaatheckman1983addendum} already gives the fixed-component and characteristic-class mechanism. It is a precise partial answer to the intervention, not a classification of all oscillatory integrals.',['duistermaatheckman1983addendum'],speaker='I. M. Gelfand',publication_match='partial',reconstruction=r'The compact Hamiltonian subclass is distinguished from the unbounded scope of the informal question.',present_status=r'As of 12 November 2026 the localization answer in the specified subclass is established. The note does not define a general classification problem beyond it.')
item(691,'P001313','conjecture','The note-taker proposes replacing the circle by a nilpotent group',r'The sentence begins \ru{Гипотеза (моя)} and suggests a nilpotent Lie-group action, with a two-dimensional example expected to give two asymptotic terms.',r'No Hamiltonian, phase, measure, compactness condition, fixed-point behavior, or asymptotic parameter is specified. A group action by itself does not determine the number of nonzero stationary-phase terms. The dimension-two nilpotent case is abelian, so even the proposed mechanism is not determined by a nonabelian example.',r'The fixed-component theorem of \citet{duistermaatheckman1983addendum} is contextual, not a result matching this conjecture. The original scan confirms that the parenthetical attribution is the note-taker\textquotesingle s own.',['duistermaatheckman1983addendum'],cls='F',speaker='Notebook author (explicitly: mine)',literal_correctness='not determinable',publication_match='thematic only',confidence='low',reconstruction=r'We retain the conjectural fragment and attribution, but do not invent missing hypotheses or a class-D open problem.',present_status=r'As of 12 November 2026 the mathematical proposition intended by this sentence is not identifiable.')
corr('P001313','Duistermaat--Heckman display','(2 pi)^(-n) times a phase-free Hessian sum with omega^n','For Liouville measure omega^n/n!, use (2 pi/t)^n and signature phases, or the equivalent oriented-weight formula.','Original scan directly viewed: inverse prefactor and omitted phase are present; comparison with DH addendum Theorem (1.5).')
corr('P001313','Attribution of nilpotent-action conjecture','Hypothesis (mine)','Attribute to the notebook author, not automatically to I. M. Gelfand or V. L. Ginzburg.','Original scan and Russian transcription read «Гипотеза (моя)».',typ='provenance')
